// DPP Atlas: restyle Data Check + Rules pages, rename the list, fix wording. Run in the dpp-atlas folder:  node apply_restyle.js
const fs = require("fs"), path = require("path");
const P = (...a) => path.join(...a);
const CHECK = P("app", "[locale]", "check", "page.tsx"), RULES = P("app", "[locale]", "rules", "page.tsx");
const LAND = P("app", "[locale]", "page.tsx"), DASH = P("app", "[locale]", "dashboard", "page.tsx");
if (!fs.existsSync(CHECK) || !fs.existsSync(RULES) || !fs.existsSync(LAND)) { console.log("STOP: run this inside the dpp-atlas folder."); process.exit(1); }
const chk = fs.readFileSync(CHECK, "utf8"), rul = fs.readFileSync(RULES, "utf8"), land = fs.readFileSync(LAND, "utf8");
const done = chk.includes("ck-card") && rul.includes("ru-card");
if (done) { console.log("Already applied. Nothing to do."); process.exit(0); }
if (!chk.includes("dpp_check_v1") || (rul.match(/\{ name: "/g) || []).length !== 21 || !land.includes("dl-hero")) {
  console.log("STOP: files are not what I expected (apply_redesign.js first? pages edited by hand?). Nothing was changed."); process.exit(1);
}
fs.mkdirSync("_backup_redesign", { recursive: true });
fs.copyFileSync(CHECK, P("_backup_redesign", "check-page.tsx.bak"));
fs.copyFileSync(RULES, P("_backup_redesign", "rules-page.tsx.bak"));
const FILES = {"app/[locale]/_ui/chrome.tsx": "", "app/[locale]/check/layout.tsx": "", "app/[locale]/check/page.tsx": "", "app/[locale]/rules/page.tsx": ""};
for (const [rel, b64] of Object.entries(FILES)) {
  fs.mkdirSync(path.dirname(rel), { recursive: true });
  fs.writeFileSync(rel, Buffer.from(b64, "base64").toString("utf8"), "utf8");
  console.log("written: " + rel);
}
function rep(file, pairs) {
  let s = fs.readFileSync(file, "utf8");
  for (const [a, b] of pairs) { const n = s.split(a).length - 1; console.log(n + "x  " + file.slice(-24) + "  " + a.slice(0, 50)); if (n >= 1) s = s.split(a).join(b); }
  fs.writeFileSync(file, s, "utf8");
}
rep(LAND, [
  ["get a Monday list:", "get an action list by owner:"],
  ["Work the Monday list", "Work the action list"],
  ["পান সোমবারের কাজের তালিকা:", "পান দায়িত্ব অনুযায়ী কাজের তালিকা:"],
  ["সোমবারের তালিকা ধরে কাজ করুন", "তালিকা ধরে একে একে কাজ করুন"],
]);
if (fs.existsSync(DASH)) rep(DASH, [
  ["Work through your Monday list", "Work through your action list"],
  ["সোমবারের তালিকা ধরে কাজ করুন", "কাজের তালিকা ধরে এগোন"],
]);
console.log("\nDone. Next: npm run build, then git add . / git commit -m \"Restyle check and rules pages\" / git push (one command at a time).");
